{
  "bioavailability_prediction": "low",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C06", "C07", "C11", "C19", "C09", "C01", "C03", "C12", "C18", "C14", "C02", "C04", "C16", "C13", "C28", "C29", "C30", "C25", "C24", "C27", "C23"],
  "contradictory_card_ids": ["C21"],
  "prediction_basis_card_ids": ["C06", "C11", "C19", "C29", "C01", "C14"],
  "claims": [
    {
      "claim": "Pentosan polysulfate, a highly sulfated polysaccharide, has measured human oral bioavailability below 1% with values of 0.5 to 1% in healthy subjects, less than 1% in humans, at most 3% in patients, and -0.1 to 0.1% in a crossover study, with most drug excreted unchanged in feces.",
      "card_ids": ["C06", "C07", "C11", "C19", "C29"]
    },
    {
      "claim": "Dextran sulfate, another sulfated polysaccharide, is reported to have poor oral bioavailability in humans and is not practically valuable as an oral agent.",
      "card_ids": ["C09"]
    },
    {
      "claim": "Zanamivir, a polar sialic-acid-like sugar bearing N-acetyl and carboxylate groups, has absolute oral bioavailability of about 2% with a range of 1 to 5% in humans and is poorly bioavailable orally in mice while readily bioavailable by systemic routes.",
      "card_ids": ["C01", "C03", "C12", "C18", "C25"]
    },
    {
      "claim": "Glucoraphanin, a sulfated glycoside, has oral bioavailability of about 5% in humans with a range of 1 to 45% across individuals, and formulation comparisons showed no significant differences between delivery matrices.",
      "card_ids": ["C14", "C22", "C26"]
    },
    {
      "claim": "Acamprosate, a small polar sulfonate, has human absolute oral bioavailability of 11 plus or minus 1%, and the rat value of about 20% from an aqueous solution does not transfer to the larger and far more polar query molecule.",
      "card_ids": ["C02", "C04", "C16", "C21"]
    },
    {
      "claim": "The query is a fully ionized sulfated disaccharide with N-acetyl, sulfate, and carboxylate groups, logD near -16, TPSA near 259, 8 hydrogen-bond donors and 13 acceptors, matching the low-permeability profile of these low-bioavailability analogs, and no evidence supports F at or above 20%.",
      "card_ids": ["C06", "C01", "C14"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C28", "C29", "C30", "C25", "C24", "C27", "C23"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C20", "C22", "C26"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C21"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query disaccharide.",
    "No data on possible active uptake, efflux, or transporter involvement for this exact molecule.",
    "Formulation effects such as the improved puerarin SLN result cannot be assessed for the query without formulation data.",
    "The near-threshold rat acamprosate value shows species and formulation variability but does not apply to the query extreme polarity."
  ],
  "decision_summary": "The query is an extremely polar fully ionized sulfated disaccharide. Direct human measurements for closely related sulfated polysaccharides such as pentosan polysulfate below 1% and dextran sulfate poor, and for polar sugar-like carboxylates such as zanamivir about 2% and glucoraphanin about 5%, all fall far below the 20% threshold. The L2 records reinforce this direction with an even lower absolute pentosan polysulfate value of -0.1 to 0.1% and confirm poor oral bioavailability across species for zanamivir and acamprosate. The only near-threshold value is the rat acamprosate result of about 20%, which comes from a much smaller molecule and does not transfer to the query. The physicochemical prior of logD -16, TPSA 259, and full ionization is consistent with negligible passive permeability. Therefore F at or above 20% is not supported and the prediction is low with high confidence."
}

